  "confidence": 60
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence contains no introduction or background text describing the current state of knowledge or important uncertainties. The abstract states only the objective ('To summarise available evidence regarding the performance metrics of validated prognostic models...') without describing existing knowledge or gaps."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved text explains the importance of or need for conducting the review. The 'How This Study Might Affect Research, Practice Or Policy' section addresses implications of findings, not the rationale for conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "A previous related systematic review appears to exist (reference 14: Buchan et al., 'Predictive models for cardiovascular and kidney outcomes in patients with type 2 diabetes: systematic review and meta-analyses', Heart 2021), and the manuscript calls itself 'this updated review' (text_21), but no retrieved evidence explicitly identifies, cites, and explains the need for this update in the introduction/rationale."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of prognostic model performance, not of intervention effects, so a mechanism of action description does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines prognostic model validation studies, not a complex intervention or delivery context, so a logic model requirement does not apply."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "OBJECTIVE To summarise available evidence regarding the performance metrics of validated prognostic models on cardiovascular and kidney outcomes in adults with type 2 diabetes mellitus.",
      "reason": "The objective is explicitly stated in the abstract, but it is not formulated using a recognised question-formulation framework (e.g., PICO or a prognostic-model framework); it is a plain narrative objective statement."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of prognostic model performance (discrimination and calibration), not a review of intervention effects, so planned comparisons in PICO format do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Studies validating prognostic models that predicted all cause and cardiovascular mortality, admission to hospital for heart failure, kidney failure, myocardial infarction, or ischaemic stroke in adults with type 2 diabetes mellitus, including people with established cardiovascular disease or chronic kidney disease, or both. Risk models evaluating composite outcomes were not eligible.",
      "reason": "Eligible study designs (validation studies), population (adults with type 2 diabetes), and outcomes are specified, but settings and follow-up requirements are not explicitly stated as eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No report characteristics (publication year, language, publication status) are specified anywhere in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "For each model and outcome, using a random effects model, the reported discrimination measures were pooled, reported as c statistics.",
      "reason": "Syntheses are grouped by individual model and outcome, but the grouping is not explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "our review excluded prognostic models solely evaluating composite outcomes, such as major adverse cardiovascular events, as our linked guideline focused on individual cardiovascular and kidney outcomes.",
      "reason": "A rationale is provided for the notable restriction excluding composite-outcome models, although it appears in the limitations/discussion section rather than the methods."
    }
  ],
  "confidence": 82
}

