{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "For each model and outcome, using a random effects model, the reported discrimination measures were pooled, reported as c statistics. Furthermore, when available, calibration plots were reconstructed and interpreted narratively.",
      "reason": "The effect measures for synthesis are specified for each outcome type: pooled c statistics for discrimination and narrative interpretation of calibration plots for calibration."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We rated certainty in relation to an acceptable discrimination threshold informed by clinician intuition. We selected a threshold of 0.7 to represent clinician intuition, based on a previous systematic review of studies evaluating discrimination of clinicians in disease areas similar to diabetes.",
      "reason": "A threshold (c statistic = 0.7) for interpreting effect size (discrimination) is reported along with its rationale (based on a previous systematic review of clinician discrimination)."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No methods are described for re-expressing synthesized results using another effect measure; results are presented as pooled c statistics and narrative calibration assessment without conversion to other measures."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "We did not use statistical measures (eg, observed to expected ratios or Hosmer-­ Lemeshow χ 2 tests) to assess model calibration, as these measures were not optimal when calculated for the entire cohort without regard to varying risk categories.",
      "reason": "The choice to assess calibration visually rather than with statistical measures is justified, but the choice of c statistics as the discrimination effect measure is not explicitly justified."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
